// Üretilen dosya: tool/ozgun/uret.py. Matematik · Limit, türev ve integrale giriş (zor).
const ozMathematics13Zor = <(String, String, List<String>, String)>[
  ('f(x) ve f(x) + g(x) fonksiyonlarının x → a iken limiti var ve sonludur. g(x) için aşağıdakilerden hangisi kesinlikle doğrudur?', 'Limiti vardır ve sonludur', ['Limiti yoktur', 'Fonksiyonunun a noktasında sürekli olduğu', 'g(a) = 0\'dır'], 'g(x) = [f(x) + g(x)] − f(x) yazılır; iki sonlu limitin farkı da sonlu bir limittir. Süreklilik ya da g(a) değeri hakkında bilgi çıkmaz.'),
  ('f(x) = 1/x ve g(x) = −1/x için x → 0 iken f ve g\'nin limitleri yoktur. Bu örnek hangi sonucu gösterir?', 'Limiti olmayan iki fonksiyonun toplamının limiti olabilir', ['Limit toplam kuralı, terimlerin limiti olmasa da her zaman geçerlidir', 'Limiti olmayan fonksiyonların toplamı tanımsız kalır', 'Toplamın limiti varsa terimlerin limiti de vardır'], 'f + g = 0 sabit fonksiyondur ve limiti 0\'dır. Toplam kuralı yalnız her iki limit de varken kullanılabilir.'),
  ('f(x) = arctan(1/x) fonksiyonunda sağdan limit ile soldan limitin farkı (sağ − sol) kaçtır?', 'π', ['0', 'π/2', '2π'], 'x → 0⁺ iken 1/x → +∞ ve arctan → π/2; x → 0⁻ iken −π/2. Fark π/2 − (−π/2) = π.'),
  ('lim (x → 2) (x² + ax + b)/(x − 2) = 5 olduğuna göre a·b çarpımı kaçtır?', '−6', ['6', '−10', '−5'], 'Limitin sonlu olması için 4 + 2a + b = 0 gerekir. Pay (x − 2)(x + m) biçimindedir ve limit 2 + m = 5 ise m = 3; a = 1, b = −6, a·b = −6.'),
  ('x → ∞ iken x − √(x² − 4x) ifadesi hangi değere yaklaşır?', '2', ['4', '0', '−2'], 'Eşlenik çarpımı 4x/(x + √(x² − 4x)) verir. x\'e bölünce 4/(1 + √(1 − 4/x)) → 4/2 = 2.'),
  ('Üstel terimlerden oluşan (5^(x+1) + 2ˣ)/(5ˣ − 3) kesrinde x pozitif yönde sınırsız artırılırsa kesir hangi değere yaklaşır?', '5', ['1', '25', '∞'], 'Pay 5·5ˣ + 2ˣ olarak yazılır. 5ˣ\'e bölününce (5 + (2/5)ˣ)/(1 − 3/5ˣ) → 5.'),
  ('f(x) = x·sin(1/x) fonksiyonu için x → ∞ iken yatay asimptot hangisidir?', 'y = 1', ['y = 0', 'y = ∞', 'Yatay asimptot yoktur'], 't = 1/x dersek sin(t)/t → 1 olur. Dolayısıyla f(x) → 1 ve y = 1 yatay asimptottur.'),
  ('x sıfıra yaklaşırken (sin x − tan x)/x³ limiti kaçtır?', '−1/2', ['1/2', '−1/12', '0'], 'sin x − tan x = sin x (cos x − 1)/cos x. (cos x − 1)/x² → −1/2 ve sin x/x → 1 olduğundan sonuç −1/2\'dir.'),
  ('x sonsuza giderken x·sin(π/x) ifadesi hangi sayıya yaklaşır?', 'π', ['1', '0', 'π/2 + 1'], 't = π/x alınırsa ifade π·(sin t / t) olur; t → 0 iken sonuç π\'dir.'),
  ('x → π/2 iken cos x / (x − π/2) oranının limiti kaçtır?', '−1', ['1', '0', '−π/2'], 'u = x − π/2 alınırsa cos x = −sin u olur. Oran −sin u / u → −1.'),
  ('x → ∞ iken ((x + 1)/(x − 1))ˣ ifadesinin limiti nedir?', 'e²', ['e', '1', 'e^(1/2)'], '(x + 1)/(x − 1) = 1 + 2/(x − 1) olduğundan üs x ≈ x − 1 için sonuç e² olur.'),
  ('x → 0 iken (cos x)^(1/x²) ifadesinin limiti aşağıdakilerden hangisidir?', 'e^(−1/2)', ['e^(1/2)', 'e^(1/2) + 1', 'e^(−2)'], 'ln limiti: ln(cos x)/x² → (−x²/2)/x² = −1/2. Böylece limit e^(−1/2) olur.'),
  ('x → 0⁺ iken x·⌊1/x⌋ çarpımının limiti kaçtır?', '1', ['0', '∞', '1/2'], '⌊1/x⌋ > 1/x − 1 olduğundan 1 − x < x⌊1/x⌋ ≤ 1 olur. İki sınır da 1\'e gider.'),
  ('f: [0, 1] → [0, 1] sürekli bir fonksiyon olsun. g(x) = f(x) − x ele alındığında hangi sonuca ulaşılır?', 'f(c) = c olan en az bir c ∈ [0, 1] vardır', ['f artan bir fonksiyondur', 'f(c) = 0 olan tek bir c vardır', 'f türevlenebilirdir'], 'g(0) = f(0) ≥ 0 ve g(1) = f(1) − 1 ≤ 0 olduğundan ara değer teoremiyle g(c) = 0, yani f(c) = c olur.'),
  ('Yarılama yöntemiyle uzunluğu 1 olan bir aralıkta kök aranıyor. Aralık uzunluğunun 1/100\'ün altına inmesi için en az kaç adım gerekir?', '7', ['6', '10', '50'], 'n adım sonra uzunluk 1/2ⁿ\'dir. 2⁶ = 64 yetmez, 2⁷ = 128 > 100 olduğundan en az 7 adım gerekir.'),
  ('x → 0 iken (x − sin x)/x³ limitini üç kez türev alarak bulunuz.', '1/6', ['1/3', '1/2', '−1/6'], 'Türevler sırasıyla (1 − cos x)/3x², sin x/6x ve cos x/6 verir; sonuç 1/6.'),
  ('x sıfıra giderken 1/x − 1/sin x farkının limiti kaçtır?', '0', ['1', '−1/2', '∞'], 'Fark (sin x − x)/(x sin x) olur; iki kez türev alınınca −sin x/(2cos x − x sin x) → 0.'),
  ('x → π/2⁻ iken tan x · cos x çarpımının limitini bulunuz.', '1', ['0', '∞', '−1'], 'tan x · cos x = sin x olarak sadeleşir; x → π/2 için sin x → 1.'),
  ('f(x) = |x| için [f(h) − f(−h)]/(2h) simetrik fark bölümü her h ≠ 0 için 0\'dır. Bu gözlem neyi gösterir?', 'Simetrik fark limitinin var olması türevlenebilirliği garanti etmez', ['f\'(0) = 0\'dır', 'f fonksiyonu 0\'da türevlenebilirdir', 'Tek yanlı türevler 0\'a eşittir'], '|x|, x = 0\'da köşelidir ve türevlenemez; simetrik farkın limiti var olsa bile türev tanımı sağlanmaz.'),
  ('f(x) = x² sin(1/x) (x ≠ 0) ve f(0) = 0 fonksiyonu için f\'(0) hangi değerdir?', '0', ['1', 'Yoktur', '−1'], '[h² sin(1/h)]/h = h sin(1/h) ve |h sin(1/h)| ≤ |h| → 0 olduğundan f\'(0) = 0.'),
  ('Parçalı tanımlı x² (x ≤ 1) ve ax + b (x > 1) kuralında 1 noktasında pürüzsüz birleşme (türevlenebilirlik) isteniyorsa a ile b\'nin toplamı kaç olur?', '1', ['2', '0', '−1'], 'Süreklilikten a + b = 1, türev eşitliğinden a = 2 bulunur; b = −1. Bu durumda a + b = 1.'),
  ('Orijinden y = x² + 1 eğrisine iki teğet çizilebilir. Bu iki teğetin eğimleri çarpımı kaçtır?', '−4', ['4', '−1', '2'], 'a noktasındaki teğet y = 2ax + 1 − a²; orijinden geçmesi için 1 − a² = 0 ve a = ±1. Eğimler 2 ve −2, çarpım −4.'),
  ('y = eˣ eğrisine orijinden çizilen teğetin eğimi nedir?', 'e', ['1', 'e²', '1/e'], 'a noktasındaki teğet y = eᵃ(x − a) + eᵃ; orijinden geçmesi için eᵃ(1 − a) = 0 ve a = 1. Eğim e¹ = e.'),
  ('y = √x eğrisinin (4, 2) noktasındaki normali y eksenini hangi noktada keser?', '(0, 18)', ['(0, −18)', '(0, 14)', '(0, 2)'], 'Teğet eğimi 1/4, normal eğimi −4\'tür. y − 2 = −4(x − 4) → x = 0 için y = 18.'),
  ('x = t², y = t³ olduğuna göre t = 1 için ikinci türev d²y/dx² değeri kaçtır?', '3/4', ['3/2', '1', '−3/4'], 'dy/dx = 3t/2; d/dt(3t/2) = 3/2, bu değer dx/dt = 2t ile bölünür: 3/(4t) ve t = 1\'de 3/4.'),
  ('y = (x + 1)(x + 2)/(x + 3) fonksiyonunun x = 0\'daki türevi logaritmik türevle hesaplanırsa kaç bulunur?', '7/9', ['2/3', '7/6', '−7/9'], 'y(0) = 2/3 ve y\'/y = 1/(x + 1) + 1/(x + 2) − 1/(x + 3) = 1 + 1/2 − 1/3 = 7/6. y\'(0) = (2/3)(7/6) = 7/9.'),
  ('f(x) = 1/(1 − x) fonksiyonunun x = 0\'daki dördüncü türevi f⁽⁴⁾(0) kaçtır?', '24', ['4', '1', '120'], 'f⁽ⁿ⁾(x) = n!/(1 − x)^(n + 1) olduğundan f⁽⁴⁾(0) = 4! = 24.'),
  ('f(x) = x² e^(−x) fonksiyonunun yerel maksimum değeri aşağıdakilerden hangisidir?', '4/e²', ['2/e', '4e²', '8/e²'], 'f\'(x) = x(2 − x)e^(−x). x = 2\'de yerel maksimum oluşur: f(2) = 4e^(−2).'),
  ('f(x) = x³ + ax² + 3x fonksiyonunun tüm gerçek sayılarda artan olması için a\'nın alabileceği tam sayı değerlerinin sayısı kaçtır?', '7', ['6', '5', '7,5'], 'f\'(x) = 3x² + 2ax + 3 ≥ 0 için diskriminant 4a² − 36 ≤ 0, yani −3 ≤ a ≤ 3. Tam sayılar −3\'ten 3\'e kadar 7 tanedir.'),
  ('f(x) = x⁴ için f\'(0) = 0 ve f\'\'(0) = 0\'dır. İkinci türev testi sonuç vermese de x = 0 için hangisi doğrudur?', 'Yerel minimum noktasıdır', ['Yerel maksimum noktasıdır', 'Büküm noktasıdır', 'Ekstremum noktası değildir'], 'f\'(x) = 4x³ işareti x = 0\'da − dan + ya geçer. Birinci türev testi yerel minimum olduğunu gösterir.'),
  ('f(x) = e^(−x²) fonksiyonunun büküm noktalarının apsisleri hangileridir?', '±√2/2', ['±1', '0', '±√2'], 'f\'\'(x) = (4x² − 2)e^(−x²) ve 4x² = 2 için x = ±1/√2 = ±√2/2; işaret değişir.'),
  ('f(x) = x⁴ − 4x³ fonksiyonu hangi aralıkta konkav aşağıdır (ikinci türevi negatiftir)?', '(0, 2)', ['(−∞, 0)', '(2, ∞)', '(−2, 0)'], 'f\'(x) = 4x³ − 12x² ve f\'\'(x) = 12x² − 24x = 12x(x − 2). Bu ifade yalnızca 0 < x < 2 için negatiftir.'),
  ('y = x² parabolü üzerindeki noktalar içinde (0, 3) noktasına en yakın olanın uzaklığı kaçtır?', '√11/2', ['√3', '3/2', '(√11 + 1)/2'], 'd² = x² + (x² − 3)². t = x² ile t² − 5t + 9 en küçük değerini t = 5/2\'de alır: 11/4. d = √11/2.'),
  ('6 m yüksekliğindeki bir lambanın altından 1,8 m boyundaki bir adam 1,5 m/s hızla yürüyor. Gölgesinin ucu kaç m/s hızla ilerler?', '15/7', ['3/2', '9/4', '21/10'], 'Benzer üçgenlerden gölge ucunun konumu s = x·6/(6 − 1,8) = (10/7)x. Hız (10/7)·1,5 = 15/7 m/s.'),
  ('Bir cismin hızı v(t) = 10 − 2t m/s\'dir. İlk 8 saniyede aldığı toplam yol (yol, yer değiştirme değil) kaç metredir?', '34', ['16', '25', '340'], 'Hız t = 5\'te işaret değiştirir. ∫₀⁵ (10 − 2t) dt = 25 ve ∫₅⁸ |10 − 2t| dt = 9. Toplam yol 34 m (yer değiştirme 16 m).'),
  ('|sin a − sin b| ≤ |a − b| eşitsizliği hangi teoremin sonucu olarak kolayca gösterilir?', 'Ortalama değer teoremi', ['Rolle teoremi', 'Sıkıştırma teoremi', 'Ara değer teoremi'], 'sin a − sin b = cos c·(a − b) ve |cos c| ≤ 1 olduğundan eşitsizlik sağlanır.'),
  ('x³ + x + 1 = 0 denkleminin yalnız bir gerçek kökü olduğu Rolle teoremi ile nasıl gösterilir?', 'İki kök olsaydı türevin sıfır olması gerekirdi, oysa f\' = 3x² + 1 > 0', ['Fonksiyonun çift olduğu gösterilerek', 'f(0) = f(1) olduğu gösterilerek', 'İkinci türevin sıfır olması gösterilerek'], 'İki ayrı kök arasında Rolle f\'(c) = 0 verirdi; fakat 3x² + 1 hiçbir zaman sıfır olmaz. Kök sayısı bir ile sınırlıdır.'),
  ('∫₀³ x/√(x + 1) dx belirli integrali kaçtır?', '8/3', ['2', '4', '−8/3'], 'u = x + 1: ∫₁⁴ (u − 1)/√u du = [(2/3)u^(3/2) − 2√u]₁⁴ = 4/3 − (−4/3) = 8/3.'),
  ('İkinci dereceden bir terimin üstel fonksiyonla çarpımı olan x²eˣ ifadesinin ilkeli, kısmi integrasyon iki kez uygulanarak nasıl bulunur?', 'eˣ(x² − 2x + 2) + C', ['eˣ(x² + 2x + 2) + C', 'eˣ(x² − 2x) + C', 'x²eˣ + C'], 'Kısmi integrasyon iki kez uygulanır: x²eˣ − 2∫ x eˣ dx = x²eˣ − 2(x − 1)eˣ.'),
  ('Ters tanjant fonksiyonunun kendisinin ilkelini bulmak için dv = dx seçerek kısmi integrasyon yaptığımızda hangi sonuç elde edilir?', 'x arctan x − (1/2) ln(1 + x²) + C', ['x arctan x + (1/2) ln(1 + x²) + C', 'arctan x/(1 + x²) + C', 'x arctan x − ln(1 + x²) + C'], 'u = arctan x, dv = dx alınırsa x arctan x − ∫ x/(1 + x²) dx = x arctan x − (1/2) ln(1 + x²).'),
  ('Karesi alınan x ile doğal logaritmanın çarpımı olan fonksiyonun, 1 ile e arasındaki belirli integralini hesaplayınız.', '(2e³ + 1)/9', ['(e³ + 1)/9', '(2e³ − 1)/9', 'e³/3'], 'İlkel (x³/3) ln x − x³/9. Sınırlarda: e³/3 − e³/9 + 1/9 = (2e³ + 1)/9.'),
  ('∫ eˣ sin x dx integrali aşağıdakilerden hangisidir?', 'eˣ(sin x − cos x)/2 + C', ['eˣ(sin x + cos x)/2 + C', 'eˣ(sin x − cos x) + C', 'eˣ·cos x + C'], 'Kısmi integrasyon iki kez uygulanınca integral kendisine döner: I = eˣ(sin x − cos x) − I → I = eˣ(sin x − cos x)/2.'),
  ('∫₀^(2π) |sin x| dx integralinin değeri kaçtır?', '4', ['0', '2', '2π'], 'Her yarım periyotta alan 2\'dir (∫₀^π sin x dx = 2), iki yarım periyot toplam 4 yapar.'),
  ('a ≤ b için |∫ₐᵇ f(x) dx| ≤ ∫ₐᵇ |f(x)| dx eşitsizliği neyi ifade eder?', 'Pozitif ve negatif alanların birbirini götürmesi mutlak alanı küçültür', ['İntegral her zaman pozitiftir', 'Eşitlik her fonksiyonda sağlanır', 'f\'nin sürekli olması gerekmez'], 'Sol taraf işaretli alanların toplamıdır, sağ taraf ise mutlak alanlar toplamı; ilki ikinciden büyük olamaz.'),
  ('∫₀^(π/2) sin x/(sin x + cos x) dx integralinin değeri, x yerine π/2 − x yazma özelliğinden yararlanılarak bulunursa kaç olur?', 'π/4', ['π/2', '1/2', '−π/4'], 'I = ∫ cos x/(sin x + cos x) dx de aynı değerdir. İkisinin toplamı ∫₀^(π/2) 1 dx = π/2 olduğundan I = π/4.'),
  ('İkinci dereceden x² − 2x ifadesiyle verilen eğri ile y = x doğrusunun çevrelediği kapalı bölgenin yüzölçümü hangisidir?', '9/2', ['9', '27/4', '3'], 'x² − 2x = x için x = 0 ve x = 3. ∫₀³ [x − (x² − 2x)] dx = ∫₀³ (3x − x²) dx = 27/2 − 9 = 9/2.'),
  ('y = x ve y = x² eğrileri arasında kalan bölge x ekseni etrafında döndürülürse oluşan cismin hacmi kaçtır?', '2π/15', ['π/6', 'π/15', '2π/45'], 'Pul (halka) yöntemi: V = π∫₀¹ (x² − x⁴) dx = π(1/3 − 1/5) = 2π/15.'),
  ('lim (x → 0) (1/x)·∫₀ˣ cos(t²) dt ifadesinin değeri nedir?', '1', ['0', '1/2', '∞'], 'L\'Hôpital veya temel teoremle, türev alınca cos(x²)/1 olur; x → 0 için 1.'),
  ('Birikim fonksiyonu g(x), (t − 2) fonksiyonunun 0\'dan x\'e kadar olan alanını biriktirmektedir. Bu birikim fonksiyonunun alabileceği en küçük değer nedir?', '−2', ['0', '−4', '2'], 'g\'(x) = x − 2, x = 2\'de işaret − dan + ya geçer. g(2) = 2 − 4 = −2.'),
  ('Simpson kuralı ile ∫₀² x² dx integrali n = 2 aralıkla hesaplanırsa hangi sonuç çıkar?', '8/3', ['3', '5/2', '2'], '(h/3)[f(0) + 4f(1) + f(2)] = (1/3)(0 + 4 + 4) = 8/3. Simpson kuralı ikinci dereceden polinomlar için kesindir.'),
  ('lim (n → ∞) [1/(n + 1) + 1/(n + 2) + ... + 1/(2n)] limiti kaçtır?', 'ln 2', ['1', '1/2', 'ln 3'], 'Toplam (1/n)·Σ 1/(1 + k/n) biçimindedir ve ∫₀¹ dx/(1 + x) = ln 2\'ye yakınsar.'),
  ('p > 0 için ∫₁^∞ x^(−p) dx integrali hangi koşulda yakınsar?', 'p > 1', ['p < 1', 'p ≥ 1/2', 'Her p için'], 'p ≠ 1 için integral lim (b^(1 − p) − 1)/(1 − p) olur; b → ∞ iken yakınsaklık yalnız 1 − p < 0, yani p > 1 durumunda olur.'),
  ('dy/dx = x/y ve y(0) = 2, y > 0 koşullarıyla y(3) kaçtır?', '√13', ['√5', '5', '√(13)/2'], 'y dy = x dx → y² = x² + C. y(0) = 2 için C = 4; y(3) = √13.'),
  ('(2, 0) noktasından y = x² parabolüne iki teğet çizilebilir. Değme noktalarının apsisleri toplamı kaçtır?', '4', ['2', '6', '−4'], 'a noktasındaki teğet y = 2ax − a² ve (2, 0)\'dan geçmesi için 4a − a² = 0 → a = 0 veya 4. Toplam 4.'),
  ('Orijinden y = ln x eğrisine çizilen teğetin eğimi kaçtır?', '1/e', ['e', '1', '1/e²'], 'a noktasındaki teğet y = (x − a)/a + ln a. Orijinden geçmesi için ln a − 1 = 0 ve a = e. Eğim 1/a = 1/e.'),
  ('y = 1/x (x > 0) eğrisinin herhangi bir noktasındaki teğetinin koordinat eksenleriyle oluşturduğu üçgenin alanı hakkında ne söylenir?', 'Teğet noktasından bağımsız olarak daima 2 birimkaredir', ['Değme noktasına göre değişir', 'Daima 1 birimkaredir', 'Alan sınırsız büyüyebilir'], 'Teğet y = −x/a² + 2/a; kesişimler (2a, 0) ve (0, 2/a). Alan (1/2)(2a)(2/a) = 2.'),
  ('y = x² ve x = y² eğrilerinin (1, 1) noktasındaki teğetleri arasındaki dar açının tanjantı kaçtır?', '3/4', ['1/2', '4/3', '−3/4'], 'Eğimler 2 ve 1/2\'dir. tan θ = |(2 − 1/2)/(1 + 1)| = (3/2)/2 = 3/4.'),
  ('f(x) = x³ + ax² + bx fonksiyonunun x = 1 ve x = 3 noktalarında yerel ekstremumu varsa a + b toplamı kaçtır?', '3', ['−3', '9', '−6'], 'f\' = 3x² + 2ax + b = 3(x − 1)(x − 3) = 3x² − 12x + 9 → a = −6, b = 9. Toplam 3.'),
  ('f(x) = ax³ + bx² fonksiyonunun x = 1\'de yerel maksimumu vardır ve bu değer 2\'dir. a ve b nedir?', 'a = −4, b = 6', ['a = 4, b = −2', 'a = −2, b = 4', 'a = 2, b = 0'], 'f\'(1) = 3a + 2b = 0 ve f(1) = a + b = 2. Çözüm a = −4, b = 6; f\'\'(1) = −12 < 0 olduğundan maksimumdur.'),
  ('f(x) = x² sin(1/x) (x ≠ 0), f(0) = 0 fonksiyonu için türev fonksiyonu f\' hakkında hangisi doğrudur?', 'f\'(0) vardır fakat f\' fonksiyonu x = 0\'da süreksizdir', ['f\' her yerde süreklidir', 'f\'(0) yoktur', 'f\'(0) = 1\'dir'], 'f\'(0) = 0 hesaplanır; ancak x ≠ 0 için f\'(x) = 2x sin(1/x) − cos(1/x) ve x → 0 iken salınım yaptığından f\' süreksizdir.'),
  ('f fonksiyonunun [0, 3] üzerindeki integrali 5\'tir. Değişken değiştirme uygulanarak argümanı üç katına çıkarılmış f(3x) fonksiyonunun [0, 1] üzerindeki integrali nedir?', '5/3', ['15', '5', '−5/3'], 'u = 3x alınırsa dx = du/3 ve integral (1/3)∫₀³ f(u) du = 5/3.'),
  ('Taban sin x, üs x olan bir kuvvet ifadesi, x pozitif yönden sıfıra yaklaşırken (sıfır üssü sıfır belirsizliği) hangi sayıya gider?', '1', ['0', 'e', '−1'], '0⁰ belirsizliğidir. ln: x ln(sin x) → 0 olduğundan limit e⁰ = 1.'),
  ('Hem tabanı hem üssü değişen x üzeri 1/ln x ifadesi, x büyüdükçe hangi değere eşit kalır ya da yaklaşır? Sonsuz üssü sıfır belirsizliği söz konusudur.', 'e', ['1', '∞', '−e'], 'x^(1/ln x) = e^((ln x)/(ln x)) = e¹ = e. İfade aslında sabittir.'),
  ('x → 1 iken 1/ln x − 1/(x − 1) farkının limiti kaçtır?', '1/2', ['0', '1', '−1/2'], 'Ortak paydada pay (x − 1) − ln x ≈ h²/2, payda ≈ h² olur (h = x − 1). Limit 1/2.'),
  ('Paydası x − 1 olan x²/(x − 1) rasyonel fonksiyonunun grafiğinin birden büyük x değerleri için çukur yaptığı en alçak noktanın ordinatı nedir?', '4', ['2', '0', '4,5'], 'f\'(x) = (x² − 2x)/(x − 1)² = 0 → x = 2 (x > 1). f(2) = 4/1 = 4.'),
  ('Kuvveti 2/3 olan kök biçimli fonksiyonun grafiği orijinde sivri uç (kıvrım) oluşturur. Bu orijin noktası hakkında hangisi söylenebilir?', 'f\'(0) tanımsızdır fakat nokta yerel minimumdur', ['Türev 0\'dır ve yerel maksimum vardır', 'Fonksiyon süreksizdir', 'Nokta bir büküm noktasıdır'], 'f\'(x) = (2/3)x^(−1/3) x = 0\'da tanımsızdır. Soldan negatif, sağdan pozitif olduğundan ve f(0) = 0 ≤ f(x) olduğundan yerel minimumdur.'),
  ('f(x) = ∛x fonksiyonunun grafiğinde x = 0 noktası için hangisi doğrudur?', 'Düşey teğetli bir büküm noktasıdır', ['Yerel minimumdur', 'Yerel maksimumdur', 'Süreksizlik noktasıdır'], 'f\'\' = −(2/9)x^(−5/3) x = 0\'ın iki yanında zıt işaretlidir; konkavlık değişir. Teğet düşeydir.'),
  ('f\' fonksiyonunun x = 2\'de yerel minimumu varsa f için x = 2 noktasında ne söylenebilir?', 'Büküm noktasıdır; f\'\' işaret değiştirir', ['Yerel maksimumdur', 'Yerel minimumdur', 'Süreksizlik noktasıdır'], 'f\'\' = (f\')\' ve f\' yerel minimumda azalandan artana geçer; yani f\'\' − dan + ya geçer, bu da f için konkavlık değişimidir.'),
  ('x → ∞ iken √(x² + ax) − x ifadesinin limiti 3 ise a kaçtır?', '6', ['3', '9', '3/2'], 'Eşlenikle ifade ax/(√(x² + ax) + x) → a/2 olur. a/2 = 3 → a = 6.'),
  ('Taban olarak (x + a)/(x − a) kesrinin alındığı, üssü x olan ifadenin sonsuzdaki limiti e⁴ ise a parametresi ne olmalıdır?', '2', ['4', '1', '−2'], 'Taban 1 + 2a/(x − a) biçimindedir ve limit e^(2a) olur. e^(2a) = e⁴ → a = 2.'),
  ('x → ∞ iken ax + b − √(x² + x + 1) ifadesinin limiti 0 olması için a + b toplamı kaç olmalıdır?', '3/2', ['1', '2', '−3/2'], 'Limitin sonlu olması a = 1 gerektirir. Bu durumda √(x² + x + 1) ≈ x + 1/2 olduğundan b − 1/2 = 0 ve b = 1/2. Toplam 3/2.'),
  ('x → 0 iken (cos(ax) − 1)/x² limiti −8 ise a\'nın mutlak değeri kaçtır?', '4', ['2', '8', '16'], '(cos(ax) − 1)/x² → −a²/2 olur. −a²/2 = −8 → a² = 16 ve |a| = 4.'),
  ('Bir öğrenci (1 − cos x)/x² ifadesini x = 10⁻⁸ için hesap makinesinde 0 buluyor. Gerçek limit 1/2 olduğuna göre bu sonuç neden yanıltıcıdır?', 'cos x değeri 1\'e çok yakın olduğundan çıkarmada hassasiyet kaybolur', ['Limit gerçekten 0\'dır', 'Hesap makinesi trigonometriyi hesaplayamaz', 'x çok büyük seçilmiştir'], 'cos(10⁻⁸) makine hassasiyetinde 1\'e eşit yuvarlanır, pay 0 olur. Bu, sayısal limit tahmininde yuvarlama hatası örneğidir.'),
  ('lim (x → 1) x² = 1 için ε = 0,3 verildi. δ = min(1, ε/3) yöntemine göre güvenli bir δ değeri hangisidir?', '0,1', ['0,3', '0,5', '−0,1'], '|x| < 2 için |x + 1| < 3 ve |x² − 1| < 3δ olur. δ = 0,1 için hata 0,3\'ten küçüktür.'),
  ('f(x) = 1 (x ≥ 0) ve f(x) = −1 (x < 0) için |f| ve f hakkında hangisi doğrudur?', '|f| sabit 1 ve süreklidir, f ise x = 0\'da süreksizdir', ['İkisi de süreklidir', 'İkisi de süreksizdir', 'f süreklidir, |f| süreksizdir'], '|f(x)| = 1 her yerde sabittir. f ise x = 0\'da −1\'den 1\'e sıçrar; |f|\'nin sürekli olması f\'nin sürekli olduğunu göstermez.'),
  ('Rasyonel sayılarda 1, irrasyonel sayılarda 0 değerini alan Dirichlet fonksiyonu için hangisi doğrudur?', 'Hiçbir noktada sürekli değildir', ['Her noktada süreklidir', 'Yalnız tam sayılarda süreklidir', 'Yalnız 0\'da süreklidir'], 'Her aralıkta hem rasyonel hem irrasyonel sayı bulunur; dolayısıyla hiçbir noktada limit f değerine eşit olmaz.'),
  ('f(x) = x (x rasyonel) ve f(x) = 0 (x irrasyonel) fonksiyonu hangi noktada sürekli olur?', 'Yalnız x = 0\'da', ['Her noktada', 'Hiçbir noktada', 'Yalnız x = 1\'de'], 'x → 0 iken her iki durumda da |f(x)| ≤ |x| → 0 olur. Diğer noktalarda rasyonel ve irrasyonel dizilerin limitleri farklıdır.'),
  ('f(1) = 3, f\'(1) = −2 ve her yerde f\'\'(x) > 0 olduğuna göre f(1,1) için aşağıdakilerden hangisi kesin olarak doğrudur?', 'f(1,1) ≥ 2,8', ['f(1,1) ≤ 2,8', 'f(1,1) = 2,8', 'f(1,1) < 2'], 'Konveks fonksiyon teğet doğrusunun üstündedir. Teğet değeri 3 − 0,2 = 2,8 olduğundan gerçek değer 2,8\'den küçük olamaz.'),
  ('Bir f fonksiyonunun 2 noktasındaki türevi 6\'dır. Fark bölümünün paydasında x − 2 yerine x² − 4 bulunursa, x değeri 2\'ye giderken elde edilen limit kaç olur?', '3/2', ['6', '3', '−3/2'], 'Ifade [f(x) − f(2)]/(x − 2)·1/(x + 2) olur ve limit f\'(2)/4 = 6/4 = 3/2.'),
  ('f fonksiyonu için f(1) = 3 ve f\'(1) = 2 verilmiştir. Karesinin artış oranını veren ifadenin, h sıfıra yaklaşırken ulaştığı değer kaçtır? İfade: [f(1 + h)² − f(1)²]/h.', '12', ['6', '18', '−12'], 'Bu, g = f² fonksiyonunun x = 1\'deki türevidir: 2f(1)f\'(1) = 2·3·2 = 12.'),
  ('f\'(a) > 0 olan ve f\' fonksiyonu sürekli olan bir f için aşağıdakilerden hangisi doğrudur?', 'a\'nın yeterince küçük bir komşuluğunda f artandır', ['f her yerde artandır', 'a bir yerel maksimumdur', 'f(a) > 0\'dır'], 'f\' sürekli olduğundan a\'nın yakınında pozitif kalır ve f orada artandır; genel bir sonuç ya da f(a)\'nın işareti çıkmaz.'),
  ('dy/dx = y² ve y(0) = 1 çözümünde y(1/2) kaçtır?', '2', ['1/2', 'e', '4'], '−1/y = x + C ve y(0) = 1 için C = −1; y = 1/(1 − x). y(1/2) = 2.'),
  ('y = √x eğrisinin altındaki [0, 1] bölgesi y ekseni etrafında döndürülürse oluşan cismin hacmi kaçtır? (kabuk yöntemi)', '4π/5', ['2π/3', 'π/2', '4π/25'], 'V = 2π∫₀¹ x·√x dx = 2π·[x^(5/2)/(5/2)]₀¹ = 2π·2/5 = 4π/5.'),
  ('Birinci bölgede y = x doğrusu ile y = x² parabolünün arasında kalan alan, dikey eksen çevresinde bir tur döndürülüyor. Pul (halka) yöntemiyle oluşan katı cismin hacmini bulunuz.', 'π/6', ['π/3', 'π/15', '2π/15'], 'Pul yöntemi (y\'ye göre): dış yarıçap √y, iç yarıçap y. V = π∫₀¹ (y − y²) dy = π(1/2 − 1/3) = π/6.'),
  ('∫ e^(x²) dx integrali hakkında hangisi doğrudur?', 'İlkeli vardır fakat elemanter fonksiyonlarla ifade edilemez', ['İlkeli yoktur', 'İlkeli e^(x²)/(2x) + C\'dir', 'İlkeli 2x·e^(x²) + C\'dir'], 'Sürekli her fonksiyonun ilkeli vardır; ancak e^(x²)\'nin ilkeli bilinen elemanter fonksiyonlarla yazılamaz (hata fonksiyonu ile ifade edilir).'),
  ('x sonsuza giderken (1 + 1/x²)ˣ ifadesinin limiti nedir?', '1', ['e', '0', '−1'], 'ln ifade: x·ln(1 + 1/x²) ≈ x·(1/x²) = 1/x → 0. Dolayısıyla limit e⁰ = 1.'),
  ('Ters hiperbolik sinüsü andıran logaritmik ifadenin, yani ln(x + √(x² + 1)) fonksiyonunun, türev fonksiyonu aşağıdakilerden hangisidir?', '1/√(x² + 1)', ['1/(x + √(x² + 1))', 'x/√(x² + 1)', '2x/(x² + 1)'], 'Zincir kuralıyla pay (1 + x/√(x² + 1)) = (√(x² + 1) + x)/√(x² + 1) olur ve sadeleşince 1/√(x² + 1) kalır.'),
  ('Küpü alınmış mutlak değer fonksiyonunun grafiği orijinde yumuşak mı yoksa köşeli midir? Orijindeki türev değeri kaçtır?', '0', ['1', '3', 'Türev yoktur'], '[|h|³ − 0]/h = h|h| → 0 olduğundan her iki yandan türev 0\'dır.'),
  ('Fermat teoremine göre bir iç noktada yerel ekstremumu olan türevlenebilir bir fonksiyon için hangisi doğrudur?', 'Bu noktada türev sıfırdır; ancak türevin sıfır olması ekstremum için yeterli değildir', ['Türev sıfırsa nokta kesin ekstremumdur', 'İkinci türev sıfır olmalıdır', 'Türev bu noktada tanımsızdır'], 'Fermat teoremi gerekli koşul verir (f\'(c) = 0). x³ örneğinde f\'(0) = 0 olduğu halde ekstremum yoktur.'),
  ('∫₋₁¹ x² e^(x³) dx integralinin değeri aşağıdakilerden hangisidir?', '(e − 1/e)/3', ['(e − 1)/3', '2e/3', '0'], 'u = x³ ile (1/3)∫₋₁¹ eᵘ du = (e − e⁻¹)/3 bulunur. İntegrand ne tek ne çifttir; bu yüzden simetri kısayolu kullanılamaz.'),
  ('Paydası iki kare farkı biçiminde olan 1/(x² − 1) kesrinin 2\'den 3\'e belirli integralini kısmi kesirlerle hesaplayınız.', '(1/2) ln(3/2)', ['ln(3/2)', '(1/2) ln 3', '1/6'], '1/(x² − 1) = (1/2)[1/(x − 1) − 1/(x + 1)]. [(1/2) ln((x − 1)/(x + 1))]₂³ = (1/2)(ln(1/2) − ln(1/3)) = (1/2) ln(3/2).'),
  ('v(t) = 3t² − 6t m/s hız fonksiyonu t = 2\'de işaret değiştirir. Cismin ilk üç saniyede toplam kaç metre yol aldığını (alınan yol, yer değiştirme değil) bulunuz.', '8', ['0', '4', '12'], 'Hız t = 2\'de işaret değiştirir. [0, 2]\'de yer değiştirme −4, [2, 3]\'te +4\'tür. Toplam yol 4 + 4 = 8 m (net yer değiştirme 0).'),
  ('Dördüncü kuvvet sinüsün çeyrek periyottaki alanını bulmak için kuvvet indirgeme özdeşliği kullanılırsa sonuç hangi π katıdır?', '3π/16', ['π/4', '3π/8', '3π/32'], 'sin⁴x = (3 − 4cos 2x + cos 4x)/8 olduğundan ortalama 3/8\'dir. (3/8)(π/2) = 3π/16.'),
  ('Paydası tam kareye tamamlanan 1/(x² + 2x + 5) fonksiyonunun belirsiz integrali nedir?', '(1/2) arctan((x + 1)/2) + C', ['arctan(x + 1) + C', '(1/2) ln(x² + 2x + 5) + C', '2 arctan((x + 1)/2) + C'], 'x² + 2x + 5 = (x + 1)² + 4 olur. ∫ dx/(u² + 4) = (1/2) arctan(u/2) formülü kullanılır.'),
  ('n sonsuza giderken (1/n)·Σ (k = 1\'den n\'ye) sin(kπ/n) toplamı hangi değere yaklaşır?', '2/π', ['2', 'π/2', '−2/π'], 'Toplam ∫₀¹ sin(πx) dx integraline yakınsar. Bu integral [−cos(πx)/π]₀¹ = 2/π.'),
  ('∫₀² x² dx için n = 4 parçalı trapez kuralı hangi yaklaşık değeri verir?', '11/4', ['15/4', '8/3', '13/4'], 'h = 1/2: (h/2)[f(0) + 2(f(1/2) + f(1) + f(3/2)) + f(2)] = (1/4)(0 + 7 + 4) = 11/4.'),
  ('y = (1/3)(x² + 2)^(3/2) eğrisinin x = 0 ile x = 3 arasında kalan kısmının yay uzunluğunu, yay uzunluğu formülüyle bulunuz.', '12', ['9', '15', '120'], 'y\' = x√(x² + 2) ve 1 + y\'² = (x² + 1)². L = ∫₀³ (x² + 1) dx = 9 + 3 = 12.'),
  ('Derece cinsinden sin 31° değeri, sin 30° = 1/2 ve cos 30° = √3/2 kullanılarak doğrusal yaklaşımla yaklaşık kaç bulunur? (1° = π/180 rad)', '≈ 0,515', ['≈ 0,500', '≈ 0,532', '≈ 0,490'], 'f(x) = sin x için Δx = π/180 ≈ 0,01745 rad: 0,5 + (√3/2)(0,01745) ≈ 0,5151.'),
  ('(2, 0) noktasının y = √x eğrisine en yakın uzaklığı kaçtır?', '√7/2', ['√3', '3/2', '√7/2 + 1'], 'd² = (x − 2)² + x; türev 2(x − 2) + 1 = 0 → x = 3/2. d² = 1/4 + 3/2 = 7/4 ve d = √7/2.'),
  ('Taban yarıçapı 3 ve yüksekliği 6 olan bir koninin içine, tabanı koninin tabanında olacak biçimde yerleştirilen dik dairesel silindirin en büyük hacmi kaçtır?', '8π', ['12π', '6π', '4π'], 'Silindirin yarıçapı r ise yüksekliği 6 − 2r\'dir. V = πr²(6 − 2r), V\' = 0 → r = 2 ve V = π·4·2 = 8π.'),
  ('Yarıçapı 4 olan bir yarım dairenin içine, bir kenarı çap üzerinde olacak biçimde çizilebilen en büyük dikdörtgenin alanı kaçtır?', '16', ['8', '32', '160'], 'A = 2x√(16 − x²) en büyük değerini x = 2√2\'de alır. A = 2·2√2·2√2 = 16.'),
  ('f(x) = x³ − 3x + 1 fonksiyonunun gerçek köklerinin sayısı için aşağıdakilerden hangisi doğrudur?', 'Üç farklı gerçek kökü vardır', ['Tek gerçek kökü vardır', 'İki gerçek kökü vardır', 'Gerçek kökü yoktur'], 'f(−2) = −1, f(−1) = 3, f(1) = −1 ve f(2) = 3 olduğundan ara değer teoremiyle (−2, −1), (−1, 1) ve (1, 2) aralıklarında birer kök bulunur.'),
];
